using System;

interface IVehiculo { void Conducir(); }

class Coche : IVehiculo { public void Conducir() { Console.WriteLine("Conduciendo Coche"); } }
class Moto : IVehiculo { public void Conducir() { Console.WriteLine("Conduciendo Moto"); } }

static class VehiculoFactory {
    public static IVehiculo CrearVehiculo(string tipo) {
        switch(tipo.ToLower()) {
            case "coche": return new Coche();
            case "moto": return new Moto();
            default: throw new ArgumentException("Desconocido");
        }
    }
}

class Program {
    static void Main() {
        var v = VehiculoFactory.CrearVehiculo("coche");
        v.Conducir();
    }
}
